import { useTranslation } from '_/i18n';
import { useLink } from './useLink';
import { useMeta } from './useMeta';

import { buildUrl } from './buildUrl';

const appTitle = document.title;

export const Support_Router_Meta: React.FC<Props> = (props) => {
  const [translate, { language }] = useTranslation('support/Router/Meta');
  const { keywords, locales, params, pathname, pathnameFr, status } = props;

  const description = props.description || translate('description');

  document.title = props.title ? `${props.title} • ${appTitle}` : appTitle;
  document.documentElement.lang = language;
  document.documentElement.setAttribute('xml:lang', language);

  useLink('alternate', locales.en?.pathname, params, 'en');
  useLink('alternate', locales.fr?.pathname, params, 'fr');
  useLink('alternate', locales.mul?.pathname, params, 'fr');
  useLink('cannonical', locales.mul?.pathname ?? pathnameFr, params);

  useMeta('http-equiv', 'Status', String(status));

  useMeta('name', 'description', description);
  useMeta('name', 'keywords', `${translate('keywords')}${keywords ? `, ${keywords}` : ''}`);

  useMeta('property', 'og:title', document.title);
  useMeta('property', 'og:description', description);
  useMeta('property', 'og:url', buildUrl(pathname, params));

  useMeta('name', 'twitter:title', document.title);
  useMeta('name', 'twitter:description', description);
  useMeta('name', 'twitter:url', buildUrl(pathname, params));

  return null;
};

export const Meta = Support_Router_Meta;
