import type { _ } from '_/types';

import { onEvent } from '@/hooks/onEvent';

export function useOrientation(override?: _.Nullish<OverrideFunction>): Orientation {
  const [orientation, setOrientation] = React.useState(getOrientation);
  onEvent(window, 'resize', updateOrientation);

  function getOrientation(): Orientation {
    return override?.() || (innerWidth >= innerHeight ? 'landscape' : 'portrait');
  }

  function updateOrientation(): void {
    setOrientation(getOrientation());
  }

  return orientation;
}
