import i18n from 'i18next';
import LanguageDetector from 'i18next-browser-languagedetector';
import * as RcI18n from 'react-i18next';

/**
 * `<I18nProvider>`: Sets up i18n for all descendants.
 * @param props.children Descendants.
 * @param props.defaultNS Default namespace.
 */
export const I18nProvider: React.FC<I18nProvider.Props> = (props, context) => {
  const { children, defaultNS, ...customOptions } = props;
  const supportedLngs = Object.keys(customOptions.resources);
  const options = {
    cleanCode: true,
    detection: {
      lookupCookie: 'lang',
      caches: ['cookie'],
      excludeCacheFor: ['cimode'],
      order: ['cookie', 'navigator'],
    },
    fallbackLng: supportedLngs[0],
    interpolation: { escapeValue: false },
    supportedLngs,
    ...customOptions,
  };
  void i18n.use(LanguageDetector).init(options);
  Object.defineProperties(i18n, {
    lang: { configurable: true, get: () => i18n.language },
    fallbackLng: { configurable: true, value: options.fallbackLng },
    resources: { configurable: true, value: customOptions.resources },
    supportedLngs: { configurable: true, value: supportedLngs },
  });
  return RcI18n.I18nextProvider({ children, defaultNS, i18n }, context);
};
