import type { _ } from '_/types';

import { useHeadTag } from './useHeadTag';

const attributes = ['http-equiv', 'name', 'property'] as const;

type Attribute = (typeof attributes)[number];

type Type = 'Status' | 'description' | 'keywords' | Media.Tag;

namespace Media {
  type Name = 'og' | 'twitter';

  type Type = 'title' | 'description' | 'url';

  export type Tag = `${Name}:${Type}`;
}

function getSortingValue(meta: HTMLMetaElement): string {
  for (const attribute of attributes) {
    const type = meta.getAttribute(attribute);
    if (type) {
      return makeSortingValue(attribute, type);
    }
  }
  return '';
}

function makeSortingValue(attribute: Attribute, type: string): string {
  const isMedia = Number(type.includes(':'));
  return `${Number(isMedia)}/${isMedia ? '' : attribute}/${type}`;
}

export function useMeta(attribute: Attribute, type: Type, content: _.Optional<string>): void {
  const meta = useHeadTag('meta', prepare, update, isBefore, content);
  const sortingValue = React.useMemo(() => makeSortingValue(attribute, type), []);

  function isBefore(otherMeta: HTMLMetaElement): boolean {
    const otherSortingValue = getSortingValue(otherMeta);
    return otherSortingValue ? sortingValue < otherSortingValue : false;
  }

  function prepare(): void {
    meta.setAttribute(attribute, type);
  }

  function update(): void {
    meta.content = content || '';
  }
}
