import type { _ } from '_/types';

export function useHeadTag<Type extends keyof HTMLElementTagNameMap>(
  type: Type,
  creator: () => void,
  updater: () => void,
  comparator: (tag: HTMLElementTagNameMap[Type]) => boolean,
  content: _.Optional<string>,
): HTMLElementTagNameMap[Type] {
  const tag = React.useMemo(createTag, []);

  React.useEffect(creator, []);
  React.useEffect(update, [content || null]);

  function createTag(): HTMLElementTagNameMap[Type] {
    return document.createElement(type);
  }

  function detach(): void {
    if (tag.parentElement === document.head) {
      document.head.removeChild(tag);
    }
  }

  function getNextSibling(): Element | null {
    let typeMatch = false;
    let fallbackEl: Element | null = null;
    for (const sibling of document.head.children) {
      if (isSameType(sibling)) {
        typeMatch = true;
        if (comparator(sibling)) {
          return sibling;
        }
      } else if (typeMatch) {
        fallbackEl = sibling;
        typeMatch = false;
      }
    }
    return fallbackEl;
  }

  function isSameType(el: Element): el is HTMLElementTagNameMap[Type] {
    return el.tagName === type.toUpperCase();
  }

  function update(): typeof detach {
    updater();
    if (!content) {
      detach();
    } else if (tag.parentElement !== document.head) {
      document.head.insertBefore(tag, getNextSibling());
    }

    return detach;
  }

  return tag;
}
