import type { Screen } from '.';

import { _ } from '_/types';
import { locales } from '@/locales';

export namespace route {
  export function fromLocales(
    namespace: Screen.Meta.Namespace,
    meta?: Partial<Screen.Meta>,
  ): Screen.Route {
    const en: Screen.Meta = { ...locales.en[namespace], ...meta };
    const fr: Screen.Meta = { ...locales.fr[namespace], ...meta };
    return { en, fr };
  }

  export function isMeta<Value>(value: Value): value is Value & Screen.Meta {
    return (
      _.isObject(value) &&
      typeof value.pathname === 'string' &&
      (value.params === void 0 || _.isObject(value.params)) &&
      (value.goto === void 0 || typeof value.goto === 'string') &&
      (value.title === void 0 || typeof value.title === 'string')
    );
  }

  export function test<Value>(value: Value): value is Value & Screen.Route {
    return (
      _.isObject(value) &&
      ((value.any === void 0 && isMeta(value.en) && isMeta(value.fr)) ||
        (isMeta(value.any) && value.en === void 0 && value.fr === void 0))
    );
  }
}
