import { z } from 'zod';
import { defaultConf } from './default';

const accessKeyRegExp = /^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/;

export const confSchema = z.object({
  backend: z.string().nullable().default(defaultConf.backend),
  gtmId: z.string().regex(/^GTM-[A-Z\d]{8,}$/),
  web3formsAccessKey: z.string().regex(accessKeyRegExp),
});

export const envSchema = z.object({
  NODE_ENV: z.enum(['development', 'production']),
  CONF: confSchema,
});
