// Load globals before other imports
import '_/react';
import '@/debug';
import 'core-js/stable';
import ReactDOM from 'react-dom/client';
import TagManager from 'react-gtm-module';
import { I18nProvider } from '_/i18n/Provider';
import { isMobile } from '_/misc/isMobile';
import { conf } from '@/conf';
import { locales } from '@/locales';
import { Router } from '@/support/Router';

import '@/assets/scss/reset.scss';
import './styles.scss';

TagManager.initialize({ gtmId: conf.gtmId });

export const appElement = document.getElementById('app') as HTMLDivElement;
appElement.className =
  window.localStorage?.getItem('__forceMobile') === 'true' || isMobile ? 'mobile' : 'desktop';

const App: React.FC = () => (
  <I18nProvider resources={locales}>
    <Router />
  </I18nProvider>
);

ReactDOM.createRoot(appElement).render(<App />);
