import type { Language } from '_/i18n';
import type { _ } from '_/types';

import { buildUrl } from './buildUrl';
import { useHeadTag } from './useHeadTag';

export function useLink(
  rel: 'cannonical' | 'alternate',
  pathname: _.Optional<string>,
  params: _.Dict<string>,
  language?: Language,
): _.Optional<string> {
  const newPathname = (pathname !== '*' && pathname) || '';
  const url = newPathname ? buildUrl(newPathname, params) : '';
  const link = useHeadTag('link', prepare, update, isBefore, url);

  function isBefore(otherLink: HTMLLinkElement): boolean {
    if (rel !== otherLink.rel) {
      return rel < otherLink.rel;
    } else if (language !== otherLink.hreflang) {
      return otherLink.hreflang ? link.hreflang < otherLink.hreflang : true;
    } else {
      return url < otherLink.href;
    }
  }

  function prepare(): void {
    link.rel = rel;
    if (language) {
      link.hreflang = language;
    }
  }

  function update(): void {
    link.href = url;
  }

  return url;
}
